import { describe, expect, it } from "vitest";
import keccakJson from "./vectors/keccak.json";
import { keccak256Hex } from "../evm";

const vectors = keccakJson as {
  repeatA: Array<{ length: number; hash: string }>;
  utf8: Array<{ text: string; hash: string }>;
};

/*
 * Keccak-256 hashes generated by Foundry `cast keccak`.
 *
 * The sweep exists because of a real bug: the padding loop was a no-op when the
 * message plus the 0x01 domain byte exactly filled a 136-byte block, producing
 * an extra all-zero block. Only lengths ≡ 135 (mod 136) were wrong, which is
 * exactly the kind of gap a handful of hand-picked vectors misses — and a
 * 135-byte signature is an ordinary long admin function.
 */
describe("keccak256 goldens", () => {
  it("covers both sides of every block boundary", () => {
    const lengths = new Set(vectors.repeatA.map((vector) => vector.length));
    // 0 is the floor, so its two hypothetical predecessors do not exist.
    for (const boundary of [136, 272]) {
      for (const offset of [-2, -1, 0, 1]) {
        expect(lengths.has(boundary + offset), `missing length ${boundary + offset}`).toBe(true);
      }
    }
    expect(lengths.has(0)).toBe(true);
  });

  it("matches the reference for every length from 0 to 300", () => {
    const mismatches = vectors.repeatA.filter((vector) => keccak256Hex("a".repeat(vector.length)) !== vector.hash);
    expect(mismatches).toEqual([]);
  });

  it("matches the reference for the known answer vectors", () => {
    expect(keccak256Hex("")).toBe("c5d2460186f7233c927e7db2dcc703c0e500b653ca82273b7bfad8045d85a470");
    expect(keccak256Hex("abc")).toBe("4e03657aea45a94fc7d47ba826c8d667c0d1e6e33a64a036ec44f58fa12d6c45");
  });

  it("hashes UTF-8 by bytes, not by code unit", () => {
    for (const vector of vectors.utf8) {
      expect(keccak256Hex(vector.text), JSON.stringify(vector.text).slice(0, 20)).toBe(vector.hash);
    }
  });

  it("accepts a byte array as well as a string", () => {
    const bytes = new TextEncoder().encode("abc");
    expect(keccak256Hex(bytes)).toBe(keccak256Hex("abc"));
  });
});
